import bcrypt from 'bcryptjs';
import { userDao } from 'dynamo/daos';
import express from 'express';
import { Passport } from 'passport';
import request from 'supertest';

import configurePassport from '../../src/config/passport';

jest.mock('dynamo/daos', () => ({
  userDao: {
    getByUsername: jest.fn(),
    getByEmail: jest.fn(),
    getByIdWithSensitiveData: jest.fn(),
    getById: jest.fn(),
  },
}));

const mockUserDao = userDao as jest.Mocked<typeof userDao>;

const PASSWORD = 'correct horse battery staple';
// Generated by bcryptjs 2.4.3, the version that hashed every password stored before the bcryptjs 3 upgrade.
const LEGACY_BCRYPTJS_2_HASH = '$2a$10$DFAWtOHFyNNEH.0jLAP1meNMXlnpD/t6oxmLPusTGbVEb6O1VOGza';

const USER = { id: 'user-1', username: 'alice' };

const buildApp = () => {
  const passport = new Passport();
  configurePassport(passport as any);

  const app = express();
  app.use(express.urlencoded({ extended: true }));
  app.use(passport.initialize());
  app.post('/login', (req, res, next) => {
    passport.authenticate('local', (err: unknown, user: any, info: any) => {
      if (err) return next(err);
      return res.json({ user: user ? user.id : false, message: info?.message ?? null });
    })(req, res, next);
  });
  return app;
};

const login = (password: string) =>
  request(buildApp()).post('/login').type('form').send({ username: USER.username, password }).expect(200);

const storeHash = (passwordHash: string) => {
  mockUserDao.getByUsername.mockResolvedValue(USER as any);
  mockUserDao.getByIdWithSensitiveData.mockResolvedValue({ ...USER, passwordHash } as any);
};

describe('password login', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('with a hash stored before the bcryptjs 3 upgrade', () => {
    beforeEach(() => storeHash(LEGACY_BCRYPTJS_2_HASH));

    it('accepts the correct password', async () => {
      const res = await login(PASSWORD);

      expect(res.body).toEqual({ user: USER.id, message: null });
    });

    it('rejects a wrong password', async () => {
      const res = await login('not the password');

      expect(res.body).toEqual({ user: false, message: 'Incorrect password' });
    });
  });

  describe('with a hash created the way register and password reset do today', () => {
    beforeEach(async () => storeHash(await bcrypt.hash(PASSWORD, await bcrypt.genSalt(10))));

    it('accepts the correct password', async () => {
      const res = await login(PASSWORD);

      expect(res.body).toEqual({ user: USER.id, message: null });
    });

    it('rejects a wrong password', async () => {
      const res = await login('not the password');

      expect(res.body).toEqual({ user: false, message: 'Incorrect password' });
    });
  });
});
